CREATE TRIGGER RefCusCondition_Combined
	ON RefCusCondition
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		ZX1_DataSetPK = COALESCE(inserted.ZX1_ZZ1_Tariff, inserted.ZX1_ZZ5_Nomenclature, inserted.ZX1_ZZS_Preference),
		ZX1_DataSetCode = CASE WHEN inserted.ZX1_ZZ1_Tariff IS NOT NULL THEN 'ZZ1' ELSE CASE WHEN inserted.ZX1_ZZ5_Nomenclature IS NOT NULL THEN 'ZZ5' ELSE CASE WHEN inserted.ZX1_ZZS_Preference IS NOT NULL THEN 'ZZS' END END END 
		FROM RefCusCondition t
		JOIN inserted ON t.ZX1_PK = inserted.ZX1_PK
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.ZX1_DataSetPK, t.ZX1_DataSetCode
	FROM RefCusCondition t
	JOIN inserted ON t.ZX1_PK = inserted.ZX1_PK
	UNION
	SELECT ZX1_DataSetPK, ZX1_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

CREATE TRIGGER RefCusCondition_DataProcessingResult_Delete
	ON RefCusCondition
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.ZX1_PK
	END
GO
